<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useQuasar,copyToClipboard} from 'quasar'
import {Plus,Search,Server as ServerIcon,X,KeyRound,Copy,ExternalLink,Pencil,Trash2,RefreshCw} from 'lucide-vue-next'
import {useMonitor} from '../stores/monitor'
import {api} from '../services/api'
import {apiBase} from '../services/connection'
import {date,relative,percent} from '../services/format'
import type {Server,Point} from '../types'
import ServerTable from '../components/ServerTable.vue'
import ServerEditor from '../components/ServerEditor.vue'
import StatusBadge from '../components/StatusBadge.vue'
import MetricBar from '../components/MetricBar.vue'
import HistoryChart from '../components/HistoryChart.vue'
const store=useMonitor(),route=useRoute(),router=useRouter(),$q=useQuasar()
const search=ref(''),filter=ref('All servers'),editing=ref(false),editTarget=ref<Server|null>(null),selected=ref<Server|null>(null),points=ref<Point[]>([]),range=ref('24h'),error=ref(''),token=ref(''),busy=ref(false)
const servers=computed(()=> (store.data?.servers||[]).filter(s=>`${s.name} ${s.hostname}`.toLowerCase().includes(search.value.toLowerCase())&&(filter.value==='All servers'||(filter.value==='Needs attention'?s.health_state!=='Healthy':s.environment===filter.value))))
const remoteApi=computed(()=>{const u=new URL(apiBase(),window.location.origin);return u.protocol==='https:'&&!['localhost','127.0.0.1','[::1]'].includes(u.hostname)?u.href.replace(/\/$/,''):'https://YOUR-CRONOS-DOMAIN/api/v1'})
function shellQuote(value:string){return "'"+value.replace(/'/g,"'\\''")+"'"}
const installCommand=computed(()=>{const s=selected.value;const url=remoteApi.value;return `wget --https-only --max-redirect=0 -O install-cronos-agent.sh ${shellQuote(url+'/agent/install.sh')}\nsudo bash install-cronos-agent.sh --api-url ${shellQuote(url)} --filesystems ${shellQuote(s?.filesystems.join(',')||'/')} --services ${shellQuote(s?.required_services.join(',')||'')}`})
async function copyInstallCommand(){try{await copyToClipboard(installCommand.value);$q.notify({message:'Install command copied. Run it on the monitored Linux server.',color:'positive'})}catch{$q.notify({message:'Select and copy the command manually.',color:'warning'})}}
async function loadHistory(){if(!selected.value)return;error.value='';points.value=[];try{points.value=await api(`/servers/${selected.value.id}/metrics?range=${range.value}`)}catch(e){error.value=(e as Error).message}}
watch([()=>route.query.server,()=>store.data],()=>{const id=Number(route.query.server);const server=store.data?.servers.find(s=>s.id===id);if(server){const changed=selected.value?.id!==server.id;selected.value=server;if(changed){token.value='';void loadHistory()}}else selected.value=null},{immediate:true})
watch(range,loadHistory)
function close(){token.value='';selected.value=null;void router.replace('/servers')}
function edit(server:Server|null){editTarget.value=server;editing.value=true}
async function enroll(){if(!selected.value)return;busy.value=true;error.value='';try{const r=await api(`/servers/${selected.value.id}/agent-credentials`,{method:'POST',body:'{}'});token.value=r.token}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function rotate(){if(!selected.value)return;$q.dialog({title:'Issue agent credential?',message:'This revokes the previous agent token for this server. Copy the new token immediately.',cancel:true,persistent:true}).onOk(enroll)}
async function copyToken(){try{await copyToClipboard(token.value);$q.notify({message:'Agent token copied',color:'positive'})}catch{$q.notify({message:'Copy the token manually.',color:'warning'})}}
function retire(){if(!selected.value)return;const s=selected.value;$q.dialog({title:'Retire server?',message:`Stop monitoring ${s.name}? History will be preserved.`,cancel:true}).onOk(async()=>{try{await api(`/servers/${s.id}`,{method:'DELETE'});close();await store.refresh();$q.notify({message:'Server retired',color:'positive'})}catch(e){error.value=(e as Error).message}})}
</script>
<template><div class="page-header"><div><h1>Servers</h1><p class="subtitle">A clear view of every machine.</p></div><q-btn v-if="store.user?.is_admin" color="primary" no-caps unelevated @click="edit(null)"><Plus :size="18"/>Add server</q-btn></div><div class="list-toolbar"><label class="search-box large"><Search :size="17"/><input v-model="search" placeholder="Search by name or hostname…" aria-label="Search servers"/></label><q-select v-model="filter" :options="['All servers','Needs attention','Production','Staging','Development']" outlined dense class="filter-select"/></div><section class="panel"><header class="panel-header"><h2>Infrastructure <span class="muted">{{servers.length}}</span></h2><span class="muted">Health and availability are evaluated separately</span></header><ServerTable :servers="servers" @select="s=>router.push(`/servers?server=${s.id}`)"/></section>
<ServerEditor v-model="editing" :server="editTarget"/>
<q-dialog :model-value="!!selected" position="right" full-height @update:model-value="v=>{if(!v)close()}"><q-card v-if="selected" class="detail-panel"><header class="detail-header"><div class="detail-icon"><ServerIcon :size="25"/></div><div><h2>{{selected.name}}</h2><p>{{selected.hostname}} · {{selected.environment}}</p></div><q-btn flat round aria-label="Close server details" @click="close"><X :size="21"/></q-btn></header><div class="detail-body"><div class="detail-status"><StatusBadge :status="selected.health_state"/><StatusBadge :status="selected.availability"/><span v-if="selected.demo" class="demo-badge">Demo data</span></div><div v-if="!selected.fresh" class="notice">Telemetry {{selected.last_seen?'is stale':'has not arrived'}}. {{selected.last_seen?`Last report ${date(selected.last_seen)}.`:'Enroll the agent to begin collection.'}}</div><div class="score-summary"><span>Server health<b>{{selected.fresh?percent(selected.last_score):'—'}}</b></span><p>{{selected.fresh?'Weighted resource and service health.':'Current health is unknown.'}}<small v-if="!selected.fresh&&selected.last_score!==null">Last recorded score: {{percent(selected.last_score)}}</small></p></div><div class="detail-resource-grid"><div><MetricBar label="CPU" :value="selected.latest_metrics.cpu" :stale="!selected.fresh"/><MetricBar label="RAM" :value="selected.latest_metrics.ram" :stale="!selected.fresh"/><MetricBar label="Swap" :value="selected.latest_metrics.swap" :stale="!selected.fresh"/></div><div><small class="muted">Operating system</small><p>{{selected.os_name||'Awaiting agent'}}</p><small class="muted">Last agent report</small><p>{{relative(selected.last_seen)}}</p></div></div><div class="section-heading"><h3>Resource history</h3><q-btn-toggle v-model="range" no-caps unelevated toggle-color="primary" :options="[{label:'1h',value:'1h'},{label:'24h',value:'24h'},{label:'7d',value:'7d'}]" size="sm"/></div><HistoryChart :points="points as any"/><p class="muted caption">Bucket averages with CPU peaks and minimum health. Missing samples remain gaps.</p><h3>Health breakdown</h3><div v-for="(c,key) in selected.components" :key="key" class="detail-line"><span>{{String(key).replace(/_/g,' ')}}</span><b>{{percent(c.health)}} <small class="muted">· weight {{c.weight}}</small></b></div><h3>Filesystems</h3><div v-for="fs in selected.latest_metrics.filesystems" :key="fs.mount" class="filesystem"><b>{{fs.mount}}</b><MetricBar label="Disk" :value="fs.used_percent" :stale="!selected.fresh"/><MetricBar label="Inodes" :value="fs.inode_percent" :stale="!selected.fresh"/></div><p v-if="!selected.latest_metrics.filesystems?.length" class="muted">Awaiting filesystem data.</p><h3>Required services</h3><div v-for="name in selected.required_services" :key="name" class="detail-line"><span>{{name}}</span><StatusBadge :status="selected.fresh?(selected.latest_metrics.services?.[name]||'Unknown'):'Unknown'"/></div><p v-if="!selected.required_services.length" class="muted">Not configured.</p><h3>Independent probe</h3><p class="break-word muted">{{selected.probe_url||'Not configured. Missing telemetry alone cannot confirm a server outage.'}}</p><div v-if="error" class="error-box" role="alert">{{error}}</div><template v-if="selected.role==='admin'"><h3>Agent enrollment</h3><p class="muted">Generate a server-specific token, then install the Python agent on this machine. Rotating revokes the old token.</p><q-btn outline no-caps :disable="selected.demo" :loading="busy" @click="rotate"><KeyRound :size="16"/>Generate token</q-btn><div v-if="token" class="secret-box"><strong>Copy this token now. It is shown only once.</strong><code>{{token}}</code><q-btn flat no-caps @click="copyToken"><Copy :size="16"/>Copy token</q-btn></div><section v-if="!selected.demo" class="agent-install"><h3>Install on this server</h3><p class="muted">Run these commands on the monitored Linux server. The installer securely prompts for the token above, creates a systemd service, and starts reporting every 30 seconds.</p><div v-if="remoteApi.includes('YOUR-CRONOS-DOMAIN')" class="notice warning">Replace YOUR-CRONOS-DOMAIN with your reachable HTTPS backend hostname. This local preview address cannot be used from another server.</div><pre class="install-command">{{installCommand}}</pre><q-btn flat no-caps @click="copyInstallCommand"><Copy :size="16"/>Copy install command</q-btn><p class="muted caption">Requires Linux with systemd and apt-get or dnf. Match the filesystem paths and required services configured in Cronos.</p></section><div class="detail-actions"><q-btn flat no-caps @click="edit(selected)"><Pencil :size="16"/>Edit server</q-btn><q-btn flat no-caps color="negative" @click="retire"><Trash2 :size="16"/>Retire</q-btn></div></template></div></q-card></q-dialog>
</template>
